// Extract and normalize supplier fields from the API response
const d = items[0].json;

if (!d.supplier || d.orders === undefined || d.delivered === undefined) {
  throw new Error('Missing required supplier fields: supplier, orders, delivered');
}

return [{
  json: {
    supplier: d.supplier,
    orders: Number(d.orders),
    delivered: Number(d.delivered),
    delay: Number(d.avg_delay_days) || 0,
    category: d.category || 'General',
    region: d.region || 'Unknown'
  }
}];

// Calculate fulfillment rate and risk score using threshold variables
const d = items[0].json;
const minFulfillment = parseFloat($('Initialize Risk Config').item.json.min_fulfillment);
const maxDelay      = parseFloat($('Initialize Risk Config').item.json.max_delay);
const riskThreshold = parseInt($('Initialize Risk Config').item.json.risk_threshold);

const fulfillment = d.orders > 0 ? parseFloat((d.delivered / d.orders).toFixed(4)) : 0;
const fulfillmentPct = (fulfillment * 100).toFixed(1);

let riskScore = 0;
const flags = [];

if (fulfillment < minFulfillment) {
  riskScore += 50;
  flags.push(`Fulfillment ${fulfillmentPct}% below threshold ${(minFulfillment*100).toFixed(0)}%`);
}
if (d.delay > maxDelay) {
  riskScore += 50;
  flags.push(`Avg delay ${d.delay} days exceeds max ${maxDelay} days`);
}

const autoRisk = riskScore >= riskThreshold ? 'High' : riskScore >= 30 ? 'Medium' : 'Low';

return [{
  json: {
    ...d,
    fulfillment,
    fulfillmentPct,
    riskScore,
    autoRisk,
    flags: flags.join('; ') || 'None'
  }
}];

