// Parse the AI risk classification response safely
const raw = (items[0].json.output || '').trim();
let parsed;

try {
  parsed = JSON.parse(raw);
} catch (e) {
  const match = raw.match(/\{[\s\S]*?\}/);
  if (match) {
    try { parsed = JSON.parse(match[0]); } catch(e2) { parsed = null; }
  }
}

if (!parsed || !parsed.risk) {
  parsed = {
    risk: items[0].json.autoRisk || 'Unknown',
    reason: 'AI parse failed — fell back to rule-based score',
    confidence: 'Low'
  };
}

// Merge AI result with existing supplier metrics
const d = items[0].json;
return [{
  json: {
    supplier     : d.supplier,
    category     : d.category,
    region       : d.region,
    orders       : d.orders,
    delivered    : d.delivered,
    fulfillment  : d.fulfillment,
    fulfillmentPct: d.fulfillmentPct,
    delay        : d.delay,
    riskScore    : d.riskScore,
    flags        : d.flags,
    risk         : parsed.risk,
    reason       : parsed.reason,
    confidence   : parsed.confidence || 'Medium',
    autoRisk     : d.autoRisk
  }
}];

