// Format AI suggestions into a clean field
const raw = (items[0].json.output || '').trim();
return [{
  json: {
    suggestions: raw || 'No suggestions generated.'
  }
}];

// Normalize backup supplier list into a readable string
const backupList = items.map((item, idx) => {
  const s = item.json;
  const name = s.supplier || s.name || `Supplier ${idx+1}`;
  const score = s.reliability_score ? ` (Score: ${s.reliability_score})` : '';
  const region = s.region ? ` [${s.region}]` : '';
  return `${idx+1}. ${name}${region}${score}`;
});

return [{
  json: {
    backups: backupList.join('\n') || 'No backup suppliers found.'
  }
}];

const data = items[0].json;

const backups = data.backups || 'N/A';
const suggestions = data.suggestions || 'N/A';

const sup = data; // already merged data

return [{
  json: {
    supplier: sup.supplier,
    risk: sup.risk,
    reason: sup.reason,
    backups,
    suggestions
  }
}];

// Log Medium / Low risk supplier — no alert sent, just audit trail
const d = items[0].json;
const now = new Date().toISOString().replace('T',' ').split('.')[0] + ' UTC';
return [{
  json: {
    supplier     : d.supplier,
    risk         : d.risk,
    riskScore    : d.riskScore,
    fulfillmentPct: d.fulfillmentPct,
    delay        : d.delay,
    reason       : d.reason,
    assessedAt   : now,
    actionTaken  : `No alert — Risk level: ${d.risk}`
  }
}];
